INSERT INTO proyectos (titulo, cuota, estado, descripcion, justificacion, fecha_limite, interes_por_mora, registro, registrado_por, actualizacion, actualizado_por) VALUES
  ('Proyecto de pintura de fachadas', 'c-2025-07-esp', 'CERRADO', 'Pintura integral de las fachadas de los bloques A y B, incluyendo áreas de circulación y columnas.', 'Las fachadas presentaban deterioro avanzado por exposición a la intemperie; la asamblea aprobó el fondo especial.', '2025-09-30 18:00:00', 1, '2025-07-01 08:00:00', 'tester', '2025-07-01 08:00:00', 'tester'),
  ('Impermeabilización de techos', 'c-2025-11-esp', 'CERRADO', 'Impermeabilización con manto asfáltico en los dos bloques residenciales y casetas de bombas.', 'Filtraciones recurrentes en los últimos pisos durante la temporada de lluvias que afectaban áreas comunes y viviendas.', '2026-01-31 18:00:00', 1, '2025-11-01 08:00:00', 'tester', '2025-11-01 08:00:00', 'tester'),
  ('Renovación de seguridad electrónica', 'c-2026-02-esp', 'CERRADO', 'Cambio de cámaras de vigilancia, actualización de portones automatizados y control de acceso con tarjetas.', 'El sistema de CCTV tenía más de 8 años de operación y fallaba en puntos críticos del estacionamiento.', '2026-03-31 18:00:00', 1, '2026-02-01 08:00:00', 'tester', '2026-02-01 08:00:00', 'tester'),
  ('Reparación mayor de ascensores', 'c-2026-05-esp', 'ACTIVO', 'Reemplazo de cables de tracción, guías y modernización del tablero de control de los dos ascensores.', 'Los ascensores presentan paradas frecuentes y el diagnóstico técnico recomienda intervención mayor antes del vencimiento de la garantía.', '2026-10-31 18:00:00', 1, '2026-05-01 08:00:00', 'tester', '2026-05-01 08:00:00', 'tester'),
  ('Pavimentación de la placa de estacionamiento', 'c-2026-08-esp', 'ACTIVO', 'Pavimentación, demarcación y señalización de la placa de estacionamiento del condominio.', 'La placa presenta hundimientos y grietas que acumulan agua; la reparación evita daños estructurales mayores.', '2026-11-30 18:00:00', 1, '2026-08-01 08:00:00', 'tester', '2026-08-01 08:00:00', 'tester');
